function EXTRA(R,ICON){
 /* hook: a sealed box with two terminals, and the two insides that give the same readings (10 V open, 5 A shorted, R = 2 Ω) */
 ICON.ctBox=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${CT_box(24,24,150,112,{fill:'#343A40',st:'#212529',r:12})}${CT_T(99,100,'?',{fs:56,fw:800,a:'middle',fill:'#FFFFFF'})}${CT_L(174,52,214,52,CT_INK,4)}${CT_L(174,108,214,108,CT_INK,4)}${CT_dot(214,52)}${CT_dot(214,108)}${CT_T(236,62,'open: 10 V',{fs:24,fw:800,fill:BLU})}${CT_T(236,118,'short: 5 A',{fs:24,fw:800,fill:ORG})}</g>`;
 ICON.ctInside=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${CT_prac('v',44,170,46,136,{r:22})}${CT_T(108,30,'2 Ω',{fs:22,fw:700,a:'middle',fill:CT_MUT})}${CT_T(76,100,'10 V',{fs:22,fw:800,fill:ORG})}${CT_T(194,100,'or',{fs:26,fw:800,a:'middle',fill:CT_INK})}${CT_prac('i',232,362,46,136,{r:22,xr:336})}${CT_T(300,30,'2 Ω',{fs:22,fw:700,a:'middle',fill:CT_MUT})}${CT_T(260,100,'5 A',{fs:22,fw:800,fill:ORG})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ctSwap=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_prac('v',60,390,26,140,{r:32,rc:ORG})}${CT_T(106,96,'Vₛ',{fs:30,fw:800,fill:ORG})}${CT_T(220,178,'⇅  Iₛ = Vₛ / R',{fs:30,fw:800,a:'middle',fill:BLU})}${CT_prac('i',60,390,206,320,{r:32,rc:ORG,xr:250})}${CT_T(106,276,'Iₛ',{fs:30,fw:800,fill:ORG})}</g>`;
 ICON.ctTree=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_gr(240,165,120,{4:'tree',5:'tree',6:'tree',1:'link',2:'link',3:'link'},{w:7,lab:1,lfs:26})}</g>`;
 ICON.ctCut=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_gr(240,165,120,{2:'grey',3:'grey',5:'grey'},{w:6,nodes:false})}${CT_gr(240,165,120,{1:'hl',4:'hl',6:'hl'},{w:7})}<circle cx="360" cy="165" r="56" fill="none" stroke="${MAG}" stroke-width="5" stroke-dasharray="11 8"/></g>`;
}
